function normalisePath(pathname) {
  if (!pathname.startsWith("/")) pathname = "/" + pathname;
  if (!pathname.endsWith("/")) pathname += "/";
  return pathname.toLowerCase();
}

export async function onRequest(context) {
  if (context.request.method !== "GET" && context.request.method !== "HEAD") {
    return context.next();
  }

  const url = new URL(context.request.url);
  const path = normalisePath(url.pathname);

  if (!path.startsWith("/lego-instructions/")) {
    return context.next();
  }

  const rest = path.slice("/lego-instructions/".length);

  // The first slug segment is the set identifier. This supports normal numeric
  // set numbers, letter-prefixed magazine IDs and text identifiers already used
  // by the website.
  const match = rest.match(/^([a-z0-9]+)(?:-|\/)/i);
  if (!match) {
    return context.next();
  }

  const setNo = match[1].toUpperCase();
  const canonical = CANONICAL_BY_SET[setNo];

  if (canonical && path !== normalisePath(canonical)) {
    url.pathname = canonical;
    return Response.redirect(url.toString(), 301);
  }

  return context.next();
}
